		0o644,
	))

	var buf, errBuf bytes.Buffer
	err = runExplainCheckpoint(ctx, &buf, &errBuf, "121212", false, false, false, true, false, false, false)
	require.NoError(t, err)
	require.Contains(t, buf.String(), "raw from checkpoint_remote")
}

